const style = `<style>
.ra-graphic,.sv-graphic{display:block;width:100%;height:auto;color:var(--ink,#17233b)}
.ra-graphic text,.sv-graphic text{font-family:inherit;fill:currentColor;font-size:15px}
.ra-graphic .ra-small,.sv-graphic .sv-small{font-size:12px;fill:var(--muted,#68748a)}
.ra-graphic .ra-big{font-size:26px;font-weight:750}
.ra-graphic .ra-axis,.sv-graphic .sv-axis{stroke:var(--line,#c9d4e0);stroke-width:1.5}
.ra-status,.sv-status{min-height:2.5em;line-height:1.55}
.ra-isotope{display:inline-grid;grid-template-columns:auto auto;grid-template-rows:1fr 1fr;column-gap:.15em;vertical-align:middle;line-height:1.03;font-weight:750;font-size:1.6em}
.ra-isotope span:first-child{grid-column:1;grid-row:1;font-size:.48em;text-align:right}.ra-isotope span:nth-child(2){grid-column:1;grid-row:2;font-size:.48em;text-align:right}.ra-isotope span:last-child{grid-column:2;grid-row:1 / 3;align-self:center}
.ra-equation{display:flex;align-items:center;justify-content:center;gap:.8rem;flex-wrap:wrap;min-height:90px;font-size:1.1rem}
.ra-meter{font-variant-numeric:tabular-nums;font-weight:700}.ra-population{display:grid;grid-template-columns:repeat(20,1fr);gap:4px;max-width:600px;margin:1rem auto}.ra-population i{aspect-ratio:1;border-radius:50%;background:#2879c7;transition:background .2s,opacity .2s}.ra-population i.ra-decayed{background:#b0bac8;opacity:.28}
.ra-keydot{display:inline-block;width:.65rem;height:.65rem;border-radius:50%;margin-right:.3rem}.ra-fieldset{border:0;padding:0;margin:0}.ra-fieldset legend{font-weight:650;margin-bottom:.6rem}.ra-model-split{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.ra-model-split>*{min-width:0}.ra-bars{display:flex;align-items:end;gap:7px;height:60px}.ra-bars i{flex:1;background:#58a6cf;border-radius:4px 4px 0 0}.ra-inline-note{font-size:.88em;color:var(--muted,#68748a)}
@media(max-width:620px){.ra-model-split{grid-template-columns:1fr}.ra-population{gap:3px}.ra-graphic text,.sv-graphic text{font-size:17px}.ra-graphic .ra-small,.sv-graphic .sv-small{font-size:14px}}
@media(prefers-reduced-motion:reduce){.ra-population i{transition:none}}
</style>`;

const nuclide = (a,z,symbol) => `<span class="ra-isotope" aria-label="${symbol}, nukleontall ${a}, protontall ${z}"><span>${a}</span><span>${z}</span><span>${symbol}</span></span>`;
const elementSymbols = ['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'];
const elementNames = ['','hydrogen','helium','litium','beryllium','bor','karbon','nitrogen','oksygen','fluor','neon','natrium','magnesium','aluminium','silisium','fosfor','svovel','klor','argon','kalium','kalsium'];
const format = (v, digits=1) => Number(v).toLocaleString('nb-NO',{maximumFractionDigits:digits});
const q = (root,id) => root.querySelector(`#${id}`);
const nucleusDots = (count,cx,cy,radius,color,offset=0) => Array.from({length:Math.min(count,80)},(_,i)=>{
  const k=i+offset;const angle=k*2.399963;const r=radius*Math.sqrt((i+.5)/Math.min(count,80));
  return `<circle cx="${(cx+r*Math.cos(angle)).toFixed(1)}" cy="${(cy+r*Math.sin(angle)).toFixed(1)}" r="${Math.min(8,radius/Math.sqrt(Math.min(count,80)+1)*.66).toFixed(1)}" fill="${color}"/>`;
}).join('');

function mountRadioactivity(root,api){
  let lastTime=0;
  const pInput=q(root,'ra-protons'),nInput=q(root,'ra-neutrons'),preset=q(root,'ra-isotope-preset');
  const isotopePaint=()=>{
    const p=Number(pInput.value),n=Number(nInput.value);
    q(root,'ra-proton-out').textContent=p;q(root,'ra-neutron-out').textContent=n;
    q(root,'ra-notation').innerHTML=nuclide(p+n,p,elementSymbols[p]);
    q(root,'ra-isotope-readout').textContent=`${elementNames[p]}-${p+n}: ${p} protoner + ${n} nøytroner = ${p+n} nukleoner.`;
    q(root,'ra-built-nucleus').innerHTML=nucleusDots(p,380,133,84,'#e68956')+nucleusDots(n,380,133,81,'#448bc5',1.4);
    q(root,'ra-built-title').textContent=`Modell av ${elementNames[p]}-${p+n}, ${p} protoner og ${n} nøytroner`;
  };
  pInput.addEventListener('input',()=>{preset.value='egen';isotopePaint();});
  nInput.addEventListener('input',()=>{preset.value='egen';isotopePaint();});
  preset.addEventListener('change',()=>{if(preset.value==='egen')return;const [p,n]=preset.value.split(',');pInput.value=p;nInput.value=n;isotopePaint();});
  isotopePaint();

  const decays={
    alpha:{parent:[222,86,'Rn'],daughter:[218,84,'Po'],particle:'α',a:4,z:2,name:'He',before:'Radon-222',after:'Polonium-218',explanation:'To protoner og to nøytroner forlater kjernen som én alfapartikkel. Nukleontallet minker med fire, protontallet med to.'},
    beta:{parent:[32,15,'P'],daughter:[32,16,'S'],particle:'β⁻',a:0,z:'−1',name:'e',before:'Fosfor-32',after:'Svovel-32',explanation:'Et nøytron omdannes til et proton. Et elektron (β⁻) og et antinøytrino sendes ut. Nukleontallet er uendret, protontallet øker med én.'},
    gamma:{parent:[202,79,'Au*'],daughter:[202,79,'Au'],particle:'γ',before:'Eksitert gull-202',after:'Gull-202',explanation:'En eksitert kjerne kvitter seg med energi som et gammafoton. Antall protoner og nøytroner er uendret. Stjernen (*) betyr ekstra energi.'}
  };
  const decaySelect=q(root,'ra-decay-type');let decayStart=0;
  const decayPaint=(t=lastTime)=>{
    const d=decays[decaySelect.value];
    q(root,'ra-decay-equation').innerHTML=`${nuclide(...d.parent)}<span>→</span>${nuclide(...d.daughter)}<span>+</span>${d.particle==='γ'?'<b>γ</b>':nuclide(d.a,d.z,d.name)}${d.particle==='β⁻'?'<span class="ra-inline-note">+ antinøytrino</span>':''}`;
    q(root,'ra-decay-explanation').textContent=d.explanation;
    q(root,'ra-decay-parent').textContent=d.before;q(root,'ra-decay-daughter').textContent=d.after;
    q(root,'ra-daughter-dots').innerHTML=nucleusDots(20,420,113,43,'#e68956')+nucleusDots(25,420,113,45,'#448bc5',.5);
    const u=((t-decayStart)*.35+.24)%1;
    q(root,'ra-emission').setAttribute('transform',`translate(${480+u*218},113)`);
    q(root,'ra-emission').innerHTML=d.particle==='α'?'<circle cx="-6" cy="-6" r="6" fill="#e68956"/><circle cx="6" cy="-6" r="6" fill="#448bc5"/><circle cx="-6" cy="6" r="6" fill="#448bc5"/><circle cx="6" cy="6" r="6" fill="#e68956"/>':d.particle==='β⁻'?'<circle r="7" fill="#7459c8"/><text text-anchor="middle" y="-17">β⁻</text>':'<path d="M-18 0 Q-12 -18 -6 0 T6 0 T18 0" fill="none" stroke="#bf8b22" stroke-width="4"/>';
    q(root,'ra-decay-a').textContent=`A: ${d.parent[0]} → ${d.daughter[0]}`;q(root,'ra-decay-z').textContent=`Z: ${d.parent[1]} → ${d.daughter[1]}`;
  };
  decaySelect.addEventListener('change',()=>{decayStart=lastTime;decayPaint();api.repaint();});
  q(root,'ra-decay-again').addEventListener('click',()=>{decayStart=lastTime;decayPaint();api.repaint();});

  const timeInput=q(root,'ra-half-time'),halfPreset=q(root,'ra-half-preset'),run=q(root,'ra-half-run');
  let thresholds=[],halfTime=Number(timeInput.value),previousTime=null;
  const sample=()=>{thresholds=Array.from({length:200},()=>Math.max(Number.EPSILON,-Math.log2(1-Math.random())));};sample();
  const halfPaint=()=>{
    const mode=halfPreset.value;const T=mode==='carbon'?5730:mode==='radon'?3.8:Math.log(.5)/Math.log(5/6);
    const unit=mode==='carbon'?'år':mode==='radon'?'døgn':'kast';
    const n=thresholds.filter(x=>x>halfTime).length;const expected=200*2**(-halfTime);
    q(root,'ra-half-time-out').textContent=`${format(halfTime,2)} halveringstider`;
    q(root,'ra-half-clock').textContent=`${format(halfTime*T,mode==='carbon'?0:1)} ${unit}`;
    q(root,'ra-half-count').textContent=`${n} av 200`;
    q(root,'ra-half-expected').textContent=`${format(expected,1)} av 200`;
    q(root,'ra-half-T').textContent=`T½ = ${format(T,mode==='carbon'?0:1)} ${unit}`;
    q(root,'ra-half-kind').textContent=mode==='dice'?'Terningmodell: en sekser fjernes ved hvert kast. Tidsaksen viser et kontinuerlig forventningsmønster; virkelige kast skjer i hele steg.':'Prøven har 200 opprinnelige kjerner. Grå prikker viser kjerner som allerede er omdannet – materien er fortsatt der.';
    q(root,'ra-population').innerHTML=thresholds.map(x=>`<i${x<=halfTime?' class="ra-decayed"':''}></i>`).join('');
    q(root,'ra-population').setAttribute('aria-label',`${n} opprinnelige kjerner igjen av 200`);
    const X=t=>62+t/6*638,Y=p=>238-p/100*192;
    let path='';for(let i=0;i<=120;i++){const t=i/20;path+=`${i?'L':'M'}${X(t).toFixed(1)},${Y(100*2**-t).toFixed(1)} `;}
    q(root,'ra-half-curve').setAttribute('d',path);
    q(root,'ra-half-point').setAttribute('cx',X(halfTime));q(root,'ra-half-point').setAttribute('cy',Y(100*2**-halfTime));
    q(root,'ra-half-marker').setAttribute('x1',X(halfTime));q(root,'ra-half-marker').setAttribute('x2',X(halfTime));
    q(root,'ra-half-random-point').setAttribute('cx',X(halfTime));q(root,'ra-half-random-point').setAttribute('cy',Y(n/2));
    q(root,'ra-half-table').innerHTML=Array.from({length:7},(_,i)=>`<tr><td>${i}</td><td>${format(i*T,mode==='carbon'?0:1)} ${unit}</td><td>${format(100*2**-i,3)} %</td></tr>`).join('');
    q(root,'ra-half-chart-desc').textContent=`Etter ${format(halfTime,2)} halveringstider forventer vi ${format(100*2**-halfTime,1)} prosent igjen. Den tilfeldige prøven har ${n/2} prosent igjen.`;
  };
  timeInput.addEventListener('input',()=>{halfTime=Number(timeInput.value);halfPaint();});
  halfPreset.addEventListener('change',halfPaint);
  q(root,'ra-half-resample').addEventListener('click',()=>{sample();halfPaint();});
  q(root,'ra-half-next').addEventListener('click',()=>{halfTime=Math.min(6,Math.floor(halfTime+.001)+1);timeInput.value=halfTime;halfPaint();});
  q(root,'ra-half-reset').addEventListener('click',()=>{halfTime=0;timeInput.value=0;run.checked=false;halfPaint();});
  run.addEventListener('change',()=>{previousTime=lastTime;});
  halfPaint();
  api.onFrame(t=>{
    if(previousTime!==null&&run.checked){halfTime=Math.min(6,halfTime+Math.max(0,Math.min(1,t-previousTime))*.18);timeInput.value=halfTime;halfPaint();if(halfTime===6)run.checked=false;}
    previousTime=t;lastTime=t;decayPaint(t);
  });
}

function mountProtection(root,api){
  let lastTime=0;
  const type=q(root,'sv-radiation'),material=q(root,'sv-material'),inside=q(root,'sv-location'),thickness=q(root,'sv-thickness');
  let transmission=1,isInternal=false;
  const labels={alpha:'α',beta:'β⁻',gamma:'γ'};const colors={alpha:'#d67c3e',beta:'#785ec3',gamma:'#207eaa'};
  const paintShield=(t=lastTime)=>{
    const k=type.value,m=material.value;isInternal=inside.value==='internal';
    const cm=Number(thickness.value);q(root,'sv-thickness-out').textContent=`${format(cm,1)} cm`;
    thickness.disabled=m!=='lead';
    const noShield=m==='none'||(m==='lead'&&cm===0);
    transmission=noShield?1:k==='alpha'?0:k==='beta'?(m==='paper'?.93:0):m==='paper'?.99:m==='aluminium'?.93:2**(-cm);
    const sourceX=isInternal?597:75,barrierX=337;
    q(root,'sv-source').setAttribute('transform',`translate(${sourceX},146)`);q(root,'sv-source-symbol').textContent=labels[k];
    q(root,'sv-shield').style.opacity=noShield?'0':'1';
    q(root,'sv-shield').setAttribute('width',m==='lead'?cm*7:m==='paper'?5:16);
    q(root,'sv-shield-label').textContent=noShield?'Ingen skjerm':m==='paper'?'Papir':m==='aluminium'?'Aluminium':`${format(cm,1)} cm bly`;
    q(root,'sv-body-label').textContent=isInternal?'Kilden er inne i kroppen':'Kilden er utenfor kroppen';
    let dots='';
    for(let i=0;i<18;i++){
      const u=(t*.22+i/18)%1;const y=146+Math.sin(i*2.399)*(isInternal?24:45);
      const maxX=isInternal?(k==='alpha'?sourceX+34:k==='beta'?sourceX+65:727):(k==='alpha'?565:k==='beta'?598:727);
      const x=sourceX+(maxX-sourceX)*u;
      const representativeGamma=k==='gamma'&&i===0&&transmission>0;
      const accepted=representativeGamma||((i*7)%18+.5)/18<transmission;
      const stopAtShield=!isInternal&&x>barrierX&&!accepted;
      const stopAtSkin=!isInternal&&k==='alpha'&&x>565;
      const opacity=!isInternal&&x>barrierX&&representativeGamma?Math.max(.28,transmission):1;
      if(!stopAtShield&&!stopAtSkin)dots+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${k==='alpha'?5:k==='beta'?3.5:2.8}" fill="${colors[k]}" opacity="${opacity}"/>`;
    }
    q(root,'sv-rays').innerHTML=dots;
    q(root,'sv-internal-glow').style.opacity=isInternal?(k==='alpha'?'.85':k==='beta'?'.5':'.25'):'0';
    const captions={alpha:isInternal?'Alfapartikler avsetter mye energi over kort avstand i vevet. Et papirark utenfor kroppen beskytter ikke mot en kilde du har pustet inn eller svelget.':'Alfa har kort rekkevidde. Papir og hudens ytterste lag stanser vanligvis partiklene. Den samme kilden kan være langt mer skadelig hvis den kommer inn i kroppen.',beta:isInternal?'Betapartikler kan skade vev rundt en intern kilde. Utvendig skjerming fjerner ikke en kilde som allerede er inne i kroppen.':'Beta trenger lengre enn alfa og kan skade hud og vev. Plast eller aluminium kan brukes som skjerming; nødvendig tykkelse avhenger av energien.',gamma:isInternal?'Gammafotoner kan passere gjennom mye vev. En intern kilde bestråler kroppen før strålingen eventuelt når en skjerm utenfor.':'Gamma går lett gjennom papir og vev. Tykt bly eller betong reduserer intensiteten gradvis. Noe kan fortsatt passere.'};
    q(root,'sv-shield-caption').textContent=captions[k];
    q(root,'sv-transmission').textContent=isInternal?'Utvendig skjerm er ikke mellom kilden og vevet':noShield?'Ingen skjerm mellom kilde og kropp':k==='gamma'&&m==='lead'?`Illustrasjon: ${format(transmission*100,1)} % passerer skjermen`:transmission===0?'Partiklene stanses av skjermen':'Noe eller mye stråling passerer';
    q(root,'sv-shield-desc').textContent=`${labels[k]}-stråling, ${isInternal?'intern':'ekstern'} kilde, ${q(root,'sv-shield-label').textContent}. ${captions[k]}`;
  };
  [type,material,inside,thickness].forEach(el=>el.addEventListener('input',()=>{paintShield();api.repaint();}));
  let polarity=1;const field=q(root,'sv-field-strength');
  const fieldPaint=(t=lastTime)=>{
    const s=Number(field.value)/100;q(root,'sv-field-out').textContent=`${field.value} %`;
    q(root,'sv-top-charge').textContent=polarity===1?'+ + + + + + + + + +':'− − − − − − − − − −';
    q(root,'sv-bottom-charge').textContent=polarity===1?'− − − − − − − − − −':'+ + + + + + + + + +';
    const makePath=(bend)=>Array.from({length:61},(_,i)=>{const u=i/60;return `${i?'L':'M'}${85+u*585},${150+polarity*bend*s*u*u}`;}).join(' ');
    q(root,'sv-alpha-path').setAttribute('d',makePath(34));q(root,'sv-beta-path').setAttribute('d',makePath(-91));
    const u=(t*.2+.33)%1;const x=85+585*u;
    for(const [key,bend]of [['alpha',34],['beta',-91],['gamma',0]]){q(root,`sv-${key}-dot`).setAttribute('cx',x);q(root,`sv-${key}-dot`).setAttribute('cy',150+polarity*bend*s*u*u);}
    const alphaY=150+polarity*34*s,betaY=150-polarity*91*s;
    q(root,'sv-alpha-label').setAttribute('y',polarity===1?Math.max(181,alphaY+18):Math.min(119,alphaY-12));
    q(root,'sv-beta-label').setAttribute('y',polarity===1?Math.max(65,Math.min(124,betaY-12)):Math.min(238,Math.max(192,betaY+18)));
    q(root,'sv-field-caption').textContent=s===0?'Uten elektrisk felt går alle tre rett frem i modellen.':`Den positive alfapartikkelen bøyes mot ${polarity===1?'nederste':'øverste'} negative plate. Det negative betaelektronet bøyes motsatt vei. Gamma har ingen ladning og fortsetter rett frem.`;
  };
  field.addEventListener('input',()=>{fieldPaint();api.repaint();});
  q(root,'sv-reverse-field').addEventListener('click',()=>{polarity*=-1;fieldPaint();api.repaint();});
  paintShield();fieldPaint();api.onFrame(t=>{lastTime=t;paintShield(t);fieldPaint(t);});
}

export const topics=[{
  id:'radioaktivitet',title:'Radioaktivitet',kicker:'Fra kjerne til klokke',summary:'Isotoper, alfa–beta–gamma og hvordan radioaktive kjerner kan brukes som en klokke.',
  sections:[
    {title:'Bygg en isotop',body:`${style}<div class="concept-grid"><div class="concept"><h3>Grunnstoffet bestemmes av protonene</h3><p><b>Atomnummer Z = antall protoner.</b> Karbon har alltid seks. Endrer du protontallet, får du et annet grunnstoff.</p></div><div class="concept"><h3>Isotoper har ulike nøytrontall</h3><p><b>Nukleontall A = protoner + nøytroner.</b> C-12 og C-14 er begge karbon, men har seks og åtte nøytroner.</p></div><div class="concept"><h3>Stabil eller radioaktiv?</h3><p>En ustabil kjerne kan omdannes og sende ut stråling. <b>Radioaktivitet er en egenskap ved kjernen</b>, ikke ved elektronskallet. C-12 er stabil, C-14 er radioaktiv.</p></div></div><div class="model"><div class="controls"><label class="control">Start med<select id="ra-isotope-preset"><option value="6,6">Karbon-12</option><option value="6,8" selected>Karbon-14</option><option value="8,8">Oksygen-16</option><option value="5,6">Bor-11</option><option value="egen">Egen kombinasjon</option></select></label><label class="control">Protoner: <output id="ra-proton-out">6</output><input id="ra-protons" type="range" min="1" max="20" step="1" value="6"></label><label class="control">Nøytroner: <output id="ra-neutron-out">8</output><input id="ra-neutrons" type="range" min="0" max="25" step="1" value="8"></label></div><svg class="ra-graphic" viewBox="0 0 760 255" role="img" aria-labelledby="ra-built-title"><title id="ra-built-title">Modell av karbon-14</title><circle cx="380" cy="133" r="101" fill="none" stroke="#a7b8ca" stroke-dasharray="5 5"/><g id="ra-built-nucleus"></g><circle cx="139" cy="97" r="7" fill="#e68956"/><text x="156" y="103">Proton</text><circle cx="139" cy="135" r="7" fill="#448bc5"/><text x="156" y="141">Nøytron</text><text x="526" y="112">Kjernen</text><text x="526" y="141" class="ra-small">Elektroner er ikke vist.</text></svg><div class="readout"><span id="ra-notation">${nuclide(14,6,'C')}</span><span id="ra-isotope-readout">Karbon-14: 6 protoner + 8 nøytroner = 14 nukleoner.</span></div><p class="model-note">Prøv: legg til et nøytron. Legg så til et proton. Hva endrer navnet? Modellen beregner notasjon; den avgjør ikke om kombinasjonen finnes eller er stabil.</p></div><p class="key">Et nuklidekart ordner kjerner etter protoner og nøytroner. Isotoper av samme grunnstoff har samme protontall, men forskjellige nøytrontall.</p>`},
    {title:'Tre måter å sende ut stråling på',body:`<p>En enkelt kjerne henfaller på et tilfeldig tidspunkt. Det kan følge flere henfall før en stabil kjerne dannes. <b>Betastråling betyr her beta minus (β⁻).</b></p><div class="table-wrap"><table class="compare-table"><thead><tr><th>Type</th><th>Det som sendes ut</th><th>Endring i kjernen</th></tr></thead><tbody><tr><td><b>α alfa</b></td><td>Heliumkjerne: 2 protoner + 2 nøytroner</td><td>A minker med 4; Z minker med 2</td></tr><tr><td><b>β⁻ beta</b></td><td>Elektron og antinøytrino, dannet i henfallet</td><td>Et nøytron blir et proton: A uendret; Z øker med 1</td></tr><tr><td><b>γ gamma</b></td><td>Energirikt foton (elektromagnetisk stråling)</td><td>Kjernen mister energi; A og Z er uendret</td></tr></tbody></table></div><div class="model"><div class="controls"><label class="control">Se et henfall<select id="ra-decay-type"><option value="alpha">Radon-222: alfa</option><option value="beta">Fosfor-32: beta minus</option><option value="gamma">Eksitert gull-202: gamma</option></select></label><button id="ra-decay-again" type="button">Vis henfallet på nytt</button></div><svg class="ra-graphic" viewBox="0 0 760 224" role="img" aria-labelledby="ra-decay-title"><title id="ra-decay-title">Skjematisk illustrasjon av radioaktivt henfall</title><circle cx="150" cy="113" r="48" fill="#d3e3ee" stroke="#6091b4" stroke-width="2"/><circle cx="137" cy="103" r="12" fill="#e68956"/><circle cx="165" cy="109" r="12" fill="#448bc5"/><circle cx="150" cy="132" r="12" fill="#e68956"/><path d="M225 113H315m-12-9 12 9-12 9" stroke="#8a99ac" stroke-width="3" fill="none"/><g id="ra-daughter-dots"></g><g id="ra-emission"></g><text id="ra-decay-parent" x="150" y="190" text-anchor="middle">Radon-222</text><text id="ra-decay-daughter" x="420" y="190" text-anchor="middle">Polonium-218</text><text x="600" y="190" text-anchor="middle">Utsendt stråling</text></svg><div class="ra-equation" id="ra-decay-equation"></div><div class="readout"><span id="ra-decay-a">A: 222 → 218</span><span id="ra-decay-z">Z: 86 → 84</span></div><p id="ra-decay-explanation" class="ra-status"></p><p class="model-note">Kjernene er skjematiske, ikke i målestokk. I reaksjonslikningen stemmer summen av nukleontall og elektrisk ladning på begge sider.</p></div><details><summary>En nedbrytningsserie: fra uran til radon</summary><p>En forenklet hovedrute er <b>U-238 → Th-234 → Pa-234m → U-234 → Th-230 → Ra-226 → Rn-222 → Po-218</b>. Pa-234m er en eksitert, metastabil tilstand. Mellom U-238 og Rn-222 skjer fire alfa- og to beta minus-henfall. Gamma kan komme i tillegg når en datterkjerne går ned i energi; det er ikke et obligatorisk eget trinn mellom hvert beta-henfall. Serien fortsetter til stabilt bly-206.</p><p>Kontroller selv: fire alfa reduserer A fra 238 til 222 og Z fra 92 til 84. To β⁻ øker Z til 86: radon.</p></details>`},
    {title:'Halveringstid: tilfeldig, men forutsigbart',body:`<p><b>Halveringstiden T½</b> er tiden det tar før halvparten av et stort antall radioaktive kjerner er omdannet. Etter hver ny halveringstid halveres det som er igjen: 100 % → 50 % → 25 % → 12,5 %.</p><div class="model"><div class="controls"><label class="control">Eksempel<select id="ra-half-preset"><option value="carbon">Karbon-14</option><option value="radon">Radon-222</option><option value="dice">Terningforsøk</option></select></label><label class="control">Tid: <output id="ra-half-time-out">1,5 halveringstider</output><input id="ra-half-time" type="range" min="0" max="6" step=".01" value="1.5"></label><label class="control"><span><input type="checkbox" id="ra-half-run"> La tiden gå</span></label></div><svg class="ra-graphic" viewBox="0 0 760 310" role="img" aria-labelledby="ra-half-chart-title ra-half-chart-desc"><title id="ra-half-chart-title">Forventet andel opprinnelige kjerner som er igjen</title><desc id="ra-half-chart-desc">Kurven halveres for hver halveringstid.</desc><path d="M62 44V238H708" class="ra-axis" fill="none"/><path d="M62 142H700M62 190H700" stroke="#a5b5c7" stroke-opacity=".22"/><text x="52" y="49" text-anchor="end">100 %</text><text x="52" y="147" text-anchor="end">50 %</text><text x="52" y="195" text-anchor="end">25 %</text><text x="52" y="243" text-anchor="end">0</text>${Array.from({length:7},(_,i)=>`<text x="${62+i*638/6}" y="265" text-anchor="middle">${i}</text>`).join('')}<text x="380" y="300" text-anchor="middle">Antall halveringstider</text><path id="ra-half-curve" d="M62 46 Q160 145 700 235" stroke="#2879c7" stroke-width="3.5" fill="none"/><line id="ra-half-marker" x1="221" x2="221" y1="45" y2="238" stroke="#2879c7" stroke-dasharray="4 5" opacity=".6"/><circle id="ra-half-point" cx="221" cy="170" r="6" fill="#2879c7"/><circle id="ra-half-random-point" cx="221" cy="170" r="5" fill="#d67c3e"/><text x="392" y="62" class="ra-small">Blå: forventning · oransje: tilfeldig prøve</text></svg><div class="readout"><span id="ra-half-T">T½ = 5730 år</span><span>Tid: <b id="ra-half-clock">8595 år</b></span><span>Prøve: <b id="ra-half-count">ca. 71 av 200</b></span><span>Forventet: <b id="ra-half-expected">70,7 av 200</b></span></div><div id="ra-population" class="ra-population" role="img" aria-label="En tilfeldig prøve med 200 kjerner"></div><div class="controls"><button type="button" id="ra-half-next">Én halveringstid til</button><button type="button" id="ra-half-resample">Ny tilfeldig prøve</button><button type="button" id="ra-half-reset">Start på nytt</button></div><p class="model-note" id="ra-half-kind"></p><p class="key">En kjerne har ikke en avtale om å henfalle etter én halveringstid. Hver gjenværende kjerne har fortsatt samme sannsynlighet for å henfalle i et gitt tidsrom.</p><details><summary>Vis tabell og regneuttrykk</summary><p>Forventet mengde: <b>N = N₀ · (½)<sup>t/T½</sup></b>. For hele halveringer holder det å halvere gjentatte ganger. Aktiviteten til den opprinnelige isotopen avtar på samme måte i en lukket prøve.</p><div class="table-wrap"><table class="compare-table"><thead><tr><th>Halveringstider</th><th>Tid</th><th>Andel igjen</th></tr></thead><tbody id="ra-half-table"></tbody></table></div></details></div>`},
    {title:'C-14 gjør dødt materiale til en klokke',body:`<div class="steps"><p><b>1. Mens organismen lever:</b> Den utveksler karbon med omgivelsene, og inneholder en liten andel radioaktivt C-14.</p><p><b>2. Når den dør:</b> Opptaket av nytt karbon opphører. C-14 henfaller til nitrogen-14, mens C-12 er stabilt.</p><p><b>3. Vi måler andelen igjen:</b> Sammenlignet med forventet opprinnelig andel forteller den omtrent hvor lenge det er siden organismen døde.</p></div><p class="key">25 % C-14 igjen → to halveringer → <b>2 · 5730 = 11 460 år</b>.</p><p>Metoden brukes på tidligere levende materiale, som tre, trekull og bein, vanligvis opptil omtrent 50 000 år. Den daterer <b>ikke en vilkårlig stein</b>. Virkelige dateringer må kalibreres fordi atmosfærens C-14-innhold har variert.</p>`}
  ],
  terms:[{term:'Isotop',definition:'Variant av et grunnstoff med et bestemt antall nøytroner. Samme grunnstoff har samme protontall.'},{term:'Nukleontall A',definition:'Summen av protoner og nøytroner i en atomkjerne.'},{term:'Atomnummer Z',definition:'Antall protoner i kjernen. Bestemmer grunnstoffet.'},{term:'Radioaktivitet',definition:'Spontan omdanning av ustabile atomkjerner, med utsending av stråling.'},{term:'Alfapartikkel',definition:'En heliumkjerne med to protoner og to nøytroner, ladning +2.'},{term:'Beta minus',definition:'Henfall der et nøytron blir et proton og et elektron og et antinøytrino sendes ut.'},{term:'Gammafoton',definition:'Elektromagnetisk stråling fra en kjerne som går ned i energi.'},{term:'Halveringstid',definition:'Tiden før forventet halvparten av opprinnelige radioaktive kjerner er omdannet.'}],
  questions:[
    {id:'ra-q1',type:'mcq',level:'Start',prompt:'Karbon-12 og karbon-14 er isotoper. Hva er likt?',choices:['Antall protoner','Antall nøytroner','Nukleontallet'],correct:0,answer:'Begge har seks protoner. C-12 har seks nøytroner; C-14 har åtte.'},
    {id:'ra-q2',type:'number',level:'Start',prompt:'Astat-220 har atomnummer 85. Hvor mange nøytroner har kjernen?',value:135,tolerance:0,unit:'nøytroner',hint:'N = A − Z.',answer:'220 − 85 = <b>135 nøytroner</b>.'},
    {id:'ra-q3',type:'open',level:'Start',prompt:'Forklar forskjellen på en stabil og en radioaktiv isotop av samme grunnstoff.',hint:'Hva er likt i kjernene, og hva kan skje spontant?',answer:'De har samme protontall, men forskjellig nøytrontall. Den radioaktive isotopen har en ustabil kjerne som spontant kan omdannes og sende ut stråling. En stabil isotop har ikke observert slikt radioaktivt henfall.'},
    {id:'ra-q4',type:'mcq',level:'Start',prompt:'Hva består en alfapartikkel av?',choices:['To protoner og to nøytroner','Ett elektron','To protoner og fire nøytroner','Ett gammafoton'],correct:0,answer:'En alfapartikkel er en heliumkjerne: <b>2 p + 2 n</b>.'},
    {id:'ra-q5',type:'open',level:'Bruk',prompt:'Radon-222 har 86 protoner og sender ut én alfapartikkel. Finn datterkjernens A og Z, og skriv reaksjonen. Polonium har atomnummer 84.',answer:`A = 222 − 4 = <b>218</b>. Z = 86 − 2 = <b>84</b>.<br>${nuclide(222,86,'Rn')} → ${nuclide(218,84,'Po')} + ${nuclide(4,2,'He')}.`},
    {id:'ra-q6',type:'mcq',level:'Bruk',prompt:'Fosfor-32 (Z = 15) sender ut beta minus. Hvilken datterkjerne dannes?',choices:['Svovel-32 (Z = 16)','Silisium-28 (Z = 14)','Fosfor-31 (Z = 15)','Svovel-33 (Z = 16)'],correct:0,answer:'Et nøytron blir et proton. Z øker fra 15 til 16, mens A fortsatt er 32. Derfor dannes <b>svovel-32</b>.'},
    {id:'ra-q7',type:'open',level:'Bruk',prompt:'En elev sier: «Betastråling oppstår når et elektron løsner fra elektronskallet.» Rett forklaringen for beta minus.',answer:'Ved β⁻-henfall omdannes et nøytron <b>i kjernen</b> til et proton. Det dannes og sendes ut et elektron og et antinøytrino. Et skall-elektron som løsner, gir ionisering; det er noe annet.'},
    {id:'ra-q8',type:'mcq',level:'Start',prompt:'Hva skjer med A og Z når en eksitert kjerne sender ut gamma?',choices:['Begge er uendret','A minker med fire, Z med to','A er uendret, Z øker med én','Begge minker med én'],correct:0,answer:'Kjernen mister energi som et foton, men har fortsatt de samme protonene og nøytronene.'},
    {id:'ra-q9',type:'number',level:'Bruk',prompt:'Du starter med 40 g C-14. Halveringstiden er 5730 år. Hvor lang tid tar det før forventet 5 g av det opprinnelige C-14 er igjen?',value:17190,tolerance:1,unit:'år',hint:'40 → 20 → 10 → 5.',answer:'Tre halveringstider: <b>3 · 5730 = 17 190 år</b>.'},
    {id:'ra-q10',type:'number',level:'Bruk',prompt:'En prøve inneholder 3000 Rn-222-kjerner. Bruk forenklet halveringstid 4 døgn. Hvor mange opprinnelige kjerner forventer vi igjen etter 12 døgn?',value:375,tolerance:0,unit:'kjerner',answer:'12/4 = 3 halveringer. 3000/2³ = <b>375 kjerner</b>. Faktisk antall kan avvike fordi henfall er tilfeldig.'},
    {id:'ra-q11',type:'number',level:'Bruk',prompt:'Et gammelt trestykke har 6,25 % av sin opprinnelige C-14-andel igjen. Bruk T½ = 5730 år og se bort fra kalibrering. Hvor lenge er det siden treet døde?',value:22920,tolerance:1,unit:'år',hint:'100 → 50 → 25 → 12,5 → 6,25.',answer:'Fire halveringer: <b>4 · 5730 = 22 920 år</b>.'},
    {id:'ra-q12',type:'open',level:'Utfordring',prompt:'En skjelettbit har 27,4 % C-14 igjen sammenlignet med nylig levende materiale. Kan den være fra eldre steinalder (10 000–4000 f.Kr.)? Bruk T½ = 5730 år. Du kan lese av simuleringen og bruke år 2026 som prøvetidspunkt.',hint:'27,4 % er litt mer enn 25 %. Alderen er derfor litt mindre enn to halveringstider.',answer:'t ≈ <b>10 700 år</b>, som ved prøvetidspunkt 2026 gir omtrent 8700 f.Kr. Det passer den oppgitte perioden. Dette er en forenklet beregning; ekte C-14-dateringer kalibreres.'},
    {id:'ra-q13',type:'open',level:'Bruk',prompt:'Kan vi si hvilken av de 200 kjernene i simuleringen som henfaller først? Forklar også hvorfor to forsøk gir litt ulike resultater.',answer:'Nei. Tidspunktet for enkelthenfall er tilfeldig. Hver prøve har tilfeldige variasjoner. For mange kjerner følger andelen som er igjen likevel en tydelig halveringskurve.'},
    {id:'ra-q14',type:'open',level:'Utfordring',prompt:'U-238 har Z = 92. På veien til Rn-222 skjer fire alfa- og to beta minus-henfall. Kontroller at både A og Z blir riktig.',answer:'A: 238 − 4 · 4 = <b>222</b>. Z: 92 − 4 · 2 + 2 · 1 = <b>86</b>. Grunnstoff 86 er radon. Gamma endrer ikke denne opptellingen.'},
    {id:'ra-q15',type:'open',level:'Bruk',prompt:'Hvorfor kan vi C-14-datere trekullet fra et bål, men ikke automatisk steinene rundt bålet?',answer:'Trekullet kommer fra en organisme som tok opp karbon mens den levde. Etter døden avtar C-14-andelen. En stein har ikke den samme biologiske startklokken og kan ikke generelt dateres med C-14.'},
    {id:'ra-q16',type:'number',level:'Utfordring',prompt:'Du har 1000 g av en isotop med halveringstid 24 døgn. Omtrent hvor mange gram av den opprinnelige isotopen er igjen etter 360 døgn?',value:0.030517578125,tolerance:0.002,unit:'g',hint:'360/24 = 15 halveringer. Del 1000 på 2¹⁵.',answer:'1000 · (½)¹⁵ ≈ <b>0,0305 g</b>, omtrent 31 mg. Stoffet er omdannet, ikke forsvunnet.'}
  ],
  resources:[{label:'PhET: bygg en atomkjerne',url:'https://phet.colorado.edu/sims/html/build-a-nucleus/latest/build-a-nucleus_all.html'},{label:'DSA: radioaktive stoffer og halveringstid',url:'https://www.dsa.no/om-straling-og-radioaktivitet/hva-er-radioaktive-stoffer'},{label:'Nuklidekart: finn isotoper og henfall',url:'https://energyeducation.ca/simulations/nuclear/nuclidechart.html'}],
  mount:mountRadioactivity
},{
  id:'stralevern',title:'Stråling i bruk',kicker:'Nytte, dose og risiko',summary:'Skjerming, bakgrunnsstråling, radon og hvordan ioniserende stråling brukes i medisin og teknologi.',
  sections:[
    {title:'Ioniserende betyr at elektroner kan rives løs',body:`${style}<p>Ioniserende stråling kan danne ioner ved å rive elektroner løs fra atomer og molekyler. Den kan skade molekyler som DNA. <b>Alfa, beta, gamma og røntgen</b> er eksempler. Røntgen kan lages i et elektrisk apparat: ioniserende stråling trenger ikke komme fra en radioaktiv kilde.</p><div class="concept-grid"><div class="concept"><h3>Alfa: kort og tett</h3><p>Ladning +2. Kort rekkevidde og tett ionisering langs banen. Vanligvis stanset av papir eller hudens ytterste lag, men kan skade mye lokalt fra en kilde inne i kroppen.</p></div><div class="concept"><h3>Beta minus: et elektron</h3><p>Ladning −1. Trenger lengre enn alfa. Plast eller aluminium kan skjerme; rekkevidden avhenger av energien. Kan skade hud og vev.</p></div><div class="concept"><h3>Gamma: et foton</h3><p>Ingen ladning. Kan passere gjennom mye materiale og vev. Bly og betong <b>demper</b> strålingen; ingen bestemt tykkelse garanterer at alt stanser.</p></div></div><p class="key">«Farligst» har ikke ett svar. Det avhenger av blant annet <b>dose, strålingstype, eksponeringstid og om kilden er utenfor eller inne i kroppen</b>.</p>`},
    {title:'Utforsk skjerming og hvor kilden er',body:`<div class="model"><div class="controls"><label class="control">Stråling<select id="sv-radiation"><option value="alpha">Alfa (α)</option><option value="beta">Beta minus (β⁻)</option><option value="gamma" selected>Gamma (γ)</option></select></label><label class="control">Kildens plass<select id="sv-location"><option value="external">Utenfor kroppen</option><option value="internal">Inne i kroppen</option></select></label><label class="control">Skjerming<select id="sv-material"><option value="none">Ingen</option><option value="paper">Papir</option><option value="aluminium">Aluminium</option><option value="lead" selected>Bly</option></select></label><label class="control">Blytykkelse: <output id="sv-thickness-out">2 cm</output><input id="sv-thickness" type="range" min="0" max="6" step=".1" value="2"></label></div><svg class="sv-graphic" viewBox="0 0 760 285" role="img" aria-labelledby="sv-shield-title sv-shield-desc"><title id="sv-shield-title">Skjerming av ioniserende stråling</title><desc id="sv-shield-desc">Sammenlign strålingstyper og kildens plassering.</desc><rect x="565" y="60" width="157" height="162" rx="44" fill="#a1c7bd" fill-opacity=".2" stroke="#6b9e8d" stroke-width="2"/><text x="644" y="93" text-anchor="middle" class="sv-small">Kroppsvev</text><circle id="sv-internal-glow" cx="605" cy="146" r="38" fill="#e68956" opacity="0"/><rect id="sv-shield" x="337" y="51" width="28" height="183" rx="3" fill="#8394ac" fill-opacity=".65" stroke="#5c6d82"/><text id="sv-shield-label" x="352" y="265" text-anchor="middle">Bly</text><g id="sv-rays"></g><g id="sv-source" transform="translate(75,146)"><circle r="25" fill="#e9b94d" stroke="#9f7720" stroke-width="2"/><text id="sv-source-symbol" y="6" text-anchor="middle" style="fill:#442f12;font-size:23px;font-weight:750">γ</text></g><text x="75" y="200" text-anchor="middle">Kilde</text><text id="sv-body-label" x="530" y="29" text-anchor="middle">Kilden er utenfor kroppen</text></svg><div class="readout" id="sv-transmission">Noe stråling passerer.</div><p id="sv-shield-caption" class="sv-status"></p><p class="model-note">Skjematisk modell, ikke en beregning av dose eller nødvendig skjerming. Ved gamma er blyets halveringstykkelse satt til 1 cm bare for å vise prinsippet. I virkeligheten avhenger den av fotonenergien og geometrien.</p></div>`},
    {title:'Ladning avslører strålingen',body:`<p>Et elektrisk felt påvirker ladde partikler. Alfa og beta minus bøyes motsatt vei; gamma har ingen ladning. Ved samme startfart bøyes et elektron langt mer enn en alfapartikkel fordi massen er mye mindre.</p><div class="model"><div class="controls"><label class="control">Relativ feltstyrke: <output id="sv-field-out">80 %</output><input id="sv-field-strength" type="range" min="0" max="100" step="1" value="80"></label><button type="button" id="sv-reverse-field">Bytt polaritet</button></div><svg class="sv-graphic" viewBox="0 0 760 300" role="img" aria-labelledby="sv-field-title"><title id="sv-field-title">Alfa og beta bøyes motsatt i elektrisk felt, gamma går rett</title><rect x="186" y="28" width="453" height="17" rx="3" fill="#ce7d65"/><rect x="186" y="253" width="453" height="17" rx="3" fill="#6189b5"/><text id="sv-top-charge" x="412" y="23" text-anchor="middle">+ + + + + + + + + +</text><text id="sv-bottom-charge" x="412" y="290" text-anchor="middle">− − − − − − − − − −</text><circle cx="85" cy="150" r="12" fill="#8497ad"/><path id="sv-alpha-path" d="M85 150Q400 150 670 185" stroke="#d67c3e" stroke-width="2.5" fill="none"/><path id="sv-beta-path" d="M85 150Q400 150 670 75" stroke="#785ec3" stroke-width="2.5" fill="none"/><path d="M85 150H670" stroke="#207eaa" stroke-width="2.5" stroke-dasharray="5 4"/><circle id="sv-alpha-dot" cx="300" cy="155" r="6" fill="#d67c3e"/><circle id="sv-beta-dot" cx="300" cy="140" r="5" fill="#785ec3"/><circle id="sv-gamma-dot" cx="300" cy="150" r="4" fill="#207eaa"/><text id="sv-alpha-label" x="684" y="184">α (+2)</text><text id="sv-beta-label" x="684" y="78">β⁻ (−1)</text><text x="684" y="148">γ (0)</text></svg><p id="sv-field-caption" class="sv-status"></p><p class="model-note">Samme startfart, skjematiske baner. Avbøyningen er ikke i målestokk; partikkelenergien påvirker også en virkelig bane.</p></div>`},
    {title:'Bq måler kilden. Sv beskriver dose.',body:`<div class="concept-grid"><div class="concept"><h3>Becquerel, Bq</h3><p><b>1 Bq = ett henfall per sekund.</b> Aktivitet forteller hvor mange kjerner som omdannes i kilden, ikke direkte hvor stor dose kroppen får.</p></div><div class="concept"><h3>Sievert, Sv</h3><p>Brukes for doser som tar hensyn til strålingstype og biologisk virkning. Effektiv dose tar også hensyn til hvilket vev som bestråles. <b>1 mSv = 1000 µSv.</b></p></div><div class="concept"><h3>Bakgrunnsstråling</h3><p>Kommer blant annet fra berggrunn, radon, radioaktive stoffer i kroppen og kosmisk stråling. En geigerteller kan derfor registrere tellinger uten at en forsøkskilde er til stede.</p></div></div><p class="key">Lav dose innebærer vanligvis lav risiko. Ved lave doser er mulig økt kreftrisiko den sentrale bekymringen; svært store doser kan også gi akutte vevsskader. <b>Stråletype alene bestemmer ikke virkningen.</b></p><details><summary>Planlegg en god måling</summary><p>Mål bakgrunn over et fast tidsrom, og gjenta. Mål deretter prøven med samme måletid, avstand og retning. Sammenlign tellinger med og uten skjerm. Tellingene varierer tilfeldig, og detektoren registrerer ikke alle strålingstyper like godt.</p><p>Et resultat over bakgrunn kan tyde på aktivitet. Skjerming kan gi en pekepinn på strålingstypen, men en enkel geigerteller identifiserer ikke sikkert isotopen.</p></details>`},
    {title:'Radon: kort rekkevidde kan fortsatt gi skade',body:`<p>Radon-222 er en radioaktiv gass som dannes i uran-238s nedbrytningsserie. Den kan sive fra grunnen inn i bygninger. Ved innånding kan radon og særlig radioaktive datterstoffer gi <b>alfabestråling i luftveiene</b>.</p><p>Papir utenfor kroppen hjelper ikke mot en kilde inne i lungene. Radon er kortlivet, men <b>ny radon dannes kontinuerlig</b> fra radium i grunnen. Et kart viser områder med mulig radonfare; det erstatter ikke en måling i den enkelte bygningen.</p><p class="key">Skille som betyr noe: <b>bestråling</b> er å bli truffet av stråling. <b>Radioaktiv forurensning</b> er å få radioaktivt stoff på eller i seg. Vanlig røntgen gjør deg ikke radioaktiv.</p>`},
    {title:'Samme egenskaper kan gjøre nytte',body:`<div class="table-wrap"><table class="compare-table"><thead><tr><th>Bruk</th><th>Prinsippet</th><th>Poenget</th></tr></thead><tbody><tr><td><b>Røntgen og CT</b></td><td>Vev demper røntgen ulikt. CT tar målinger fra mange vinkler og beregner snittbilder.</td><td>Avbilde innsiden av kroppen. Krever ikke radioaktive stoffer i pasienten.</td></tr><tr><td><b>PET</b></td><td>Et radioaktivt sporstoff tilføres kroppen. Registrering av fotoner viser hvor sporstoffet er.</td><td>Undersøke funksjon og stoffskifte, ikke bare form.</td></tr><tr><td><b>Strålebehandling</b></td><td>En planlagt dose skader kreftceller. Strålingen kan komme utenfra eller fra en kilde i kroppen.</td><td>Ramme svulsten og begrense dose til friskt vev.</td></tr><tr><td><b>Målrettet behandling</b></td><td>Et molekyl kan frakte en radioaktiv isotop mot bestemte celler, for eksempel en alfa-emitter.</td><td>Avsette energi nær målcellene.</td></tr><tr><td><b>Sterilisering</b></td><td>Ioniserende stråling skader mikroorganismer og arvestoffet deres.</td><td>Sterilisere blant annet medisinsk utstyr.</td></tr></tbody></table></div><p>Ved medisinsk bruk veies forventet nytte opp mot risiko. Diagnose og behandling har forskjellige mål og doser.</p>`},
    {title:'Fisjon og fusjon frigjør kjerneenergi',body:`<div class="concept-grid"><div class="concept"><h3>Fisjon: en tung kjerne deles</h3><p>Et nøytron kan utløse spalting av U-235. Det frigjøres energi og nye nøytroner, som kan utløse flere spaltinger: en <b>kjedereaksjon</b>. Kontrollstaver absorberer nøytroner og regulerer reaksjonen.</p></div><div class="concept"><h3>Fusjon: lette kjerner slås sammen</h3><p>Lette kjerner kan danne en tyngre kjerne og frigjøre energi. Solas energi kommer fra fusjon. Positive kjerner frastøter hverandre, så fusjon krever ekstreme forhold.</p></div></div><svg class="sv-graphic" viewBox="0 0 760 215" role="img" aria-labelledby="sv-nuclear-title"><title id="sv-nuclear-title">Fisjon deler en tung kjerne; fusjon samler lette kjerner</title><text x="185" y="30" text-anchor="middle">Fisjon</text><circle cx="84" cy="113" r="31" fill="#5a9ac6"/><circle cx="32" cy="113" r="5" fill="#8ba0b5"/><path d="M128 113H190m-10-7 10 7-10 7" stroke="#8ba0b5" stroke-width="2" fill="none"/><circle cx="225" cy="91" r="21" fill="#df9c69"/><circle cx="236" cy="139" r="18" fill="#5a9ac6"/><circle cx="286" cy="94" r="5" fill="#8ba0b5"/><circle cx="290" cy="139" r="5" fill="#8ba0b5"/><text x="185" y="194" text-anchor="middle" class="sv-small">Tung kjerne → lettere kjerner + nøytroner + energi</text><line x1="380" x2="380" y1="42" y2="173" class="sv-axis"/><text x="572" y="30" text-anchor="middle">Fusjon</text><circle cx="463" cy="92" r="16" fill="#df9c69"/><circle cx="463" cy="136" r="19" fill="#5a9ac6"/><path d="M505 113H565m-10-7 10 7-10 7" stroke="#8ba0b5" stroke-width="2" fill="none"/><circle cx="615" cy="113" r="27" fill="#7699b3"/><path d="M657 113h35m-7-6 7 6-7 6" stroke="#ce9c35" stroke-width="3" fill="none"/><text x="572" y="194" text-anchor="middle" class="sv-small">Lette kjerner → tyngre kjerne + energi</text></svg><p class="model-note">Figuren viser prinsippet, ikke en bestemt balansert reaksjonslikning. For reaksjoner som frigjør energi, er samlet masse etter reaksjonen litt mindre. Forskjellen frigjøres som energi: E = mc².</p><details><summary>Drøft kjernekraft</summary><p>Kjernekraft gir mye energi fra lite brensel og lave direkte CO₂-utslipp under drift. Samtidig må blant annet radioaktivt avfall, ulykker, kostnader og byggetid håndteres. Skill mellom en kontrollert reaktor, en våpeneksplosjon og fusjon i sola.</p></details>`}
  ],
  terms:[{term:'Ionisering',definition:'At et atom eller molekyl får netto ladning, for eksempel fordi et elektron rives løs.'},{term:'Becquerel (Bq)',definition:'Enhet for aktivitet. Ett henfall per sekund.'},{term:'Sievert (Sv)',definition:'Enhet for dose som tar hensyn til biologisk virkning; effektiv dose inkluderer vekting av bestrålt vev.'},{term:'Bakgrunnsstråling',definition:'Stråling som finnes i omgivelsene uten den bestemte forsøkskilden, blant annet fra naturlige radioaktive stoffer og verdensrommet.'},{term:'Radon',definition:'Radioaktiv edelgass fra naturlige henfallsserier; Rn-222 dannes fra Ra-226.'},{term:'Skjerming',definition:'Materiale mellom en strålekilde og det som skal beskyttes, som stopper partikler eller demper strålingen.'},{term:'Fisjon',definition:'Spalting av en tung atomkjerne til lettere kjerner.'},{term:'Fusjon',definition:'Sammensmelting av lette atomkjerner.'}],
  questions:[
    {id:'sv-q1',type:'mcq',level:'Start',prompt:'Hva betyr at stråling er ioniserende?',choices:['Den kan rive elektroner løs fra atomer eller molekyler','Den gjør alle materialer radioaktive','Den er alltid synlig','Den kommer alltid fra en atomkjerne'],correct:0,answer:'Ioniserende stråling kan danne ioner. Den trenger ikke komme fra radioaktivitet; et røntgenapparat kan også lage ioniserende stråling.'},
    {id:'sv-q2',type:'mcq',level:'Start',prompt:'Hvilken stråling består av fotoner og har ingen elektrisk ladning?',choices:['Gamma','Alfa','Beta minus'],correct:0,answer:'Gamma er elektromagnetisk stråling. Alfa er positive heliumkjerner; beta minus er negative elektroner.'},
    {id:'sv-q3',type:'open',level:'Bruk',prompt:'En alfakilde er lite farlig utenfor kroppen, men kan være skadelig ved innånding. Forklar uten å bruke uttrykket «sterkere stråling».',answer:'Alfapartikler har kort rekkevidde og stanses vanligvis av hudens ytterste lag. Inne i kroppen kan de avsette mye energi over en svært kort avstand i levende vev og skade celler.'},
    {id:'sv-q4',type:'open',level:'Bruk',prompt:'Hvorfor er «5 cm bly stopper all gammastråling» en upresis påstand?',answer:'Gamma dempes gradvis når fotoner vekselvirker med blyet. Noen kan fortsatt passere. Gjennomtrengningen avhenger blant annet av fotonenergi, tykkelse og geometri. En tykkelse er ikke en universell stoppgrense.'},
    {id:'sv-q5',type:'mcq',level:'Bruk',prompt:'I et elektrisk felt er øverste plate positiv og nederste negativ. Hvilken vei bøyes beta minus?',choices:['Mot øverste plate','Mot nederste plate','Den bøyes ikke'],correct:0,answer:'Beta minus er negativt ladde elektroner, og trekkes mot den positive platen. Alfa bøyes motsatt. Gamma går rett.'},
    {id:'sv-q6',type:'open',level:'Utfordring',prompt:'Hvorfor kan betapartikler få større avbøyning enn alfapartikler i samme elektriske felt? Anta samme startfart.',answer:'Elektronet har svært mye mindre masse. Akselerasjonen bestemmes av kraft delt på masse, og forholdet mellom ladning og masse er langt større for elektronet. Den lille massen gir større avbøyning; fortegnet til ladningen bestemmer retningen.'},
    {id:'sv-q7',type:'number',level:'Start',prompt:'En kilde har aktiviteten 250 Bq. Hvor mange henfall skjer i gjennomsnitt i løpet av 20 sekunder? Anta at aktiviteten endrer seg ubetydelig.',value:5000,tolerance:0,unit:'henfall',answer:'250 henfall/s · 20 s = <b>5000 henfall</b> i gjennomsnitt. Tallet er ikke antall registrerte tellinger i en vilkårlig detektor.'},
    {id:'sv-q8',type:'number',level:'Start',prompt:'Hvor mange mikrosievert er 2,5 mSv?',value:2500,tolerance:0,unit:'µSv',answer:'1 mSv = 1000 µSv. 2,5 mSv = <b>2500 µSv</b>.'},
    {id:'sv-q9',type:'open',level:'Bruk',prompt:'To kilder har samme aktivitet i Bq. Må de gi samme effektive dose i Sv til en person? Begrunn.',answer:'Nei. Aktivitet beskriver henfall i kildene. Dose avhenger også av strålingstype, energi, avstand, skjerming, eksponeringstid, opptak i kroppen og hvilke organer som bestråles.'},
    {id:'sv-q10',type:'open',level:'Bruk',prompt:'En geigerteller registrerer tellinger selv om forsøkskilden er lagt bort. Gi minst tre mulige naturlige kilder.',answer:'Kosmisk stråling, radioaktive stoffer i berggrunn og byggematerialer, radon og radondøtre, og naturlige radioaktive stoffer i kroppen og mat. Det kan også finnes bakgrunn i instrumentet.'},
    {id:'sv-q11',type:'open',level:'Bruk',prompt:'Radon-222 har halveringstid omtrent 3,8 døgn. Hvorfor kan en kjeller ha radon over mange år?',answer:'Radon tilføres stadig ved henfall av radium i grunnen. Kort halveringstid betyr derfor ikke at problemet automatisk forsvinner: ny gass kan sive inn kontinuerlig.'},
    {id:'sv-q12',type:'open',level:'Utfordring',prompt:'Marie vil undersøke en stein med en geigerteller, papir og bly. Beskriv en måleplan, hva hun kan finne ut, og en begrensning.',answer:'Mål og gjenta bakgrunn over fast tid. Mål deretter steinen med lik geometri og måletid; gjenta med papir og bly mellom stein og detektor. Flere tellinger enn bakgrunn tyder på stråling fra steinen. Endring ved skjerming kan gi indikasjon på strålingstype. Detektorens følsomhet, statistiske variasjoner og luft/skjerm påvirker resultatet; forsøket identifiserer ikke sikkert isotopen.'},
    {id:'sv-q13',type:'mcq',level:'Bruk',prompt:'Hva skiller PET fra vanlig røntgen?',choices:['PET bruker et radioaktivt sporstoff i kroppen; vanlig røntgen bruker en ytre røntgenkilde','Røntgen bruker et radioaktivt sporstoff i kroppen; PET gjør det ikke','PET gjør alle celler radioaktive permanent','PET bruker bare radiobølger'],correct:0,answer:'Ved PET registreres stråling knyttet til et tilført sporstoff. Vanlig røntgen og CT bruker røntgenstråling fra et apparat utenfor kroppen.'},
    {id:'sv-q14',type:'open',level:'Bruk',prompt:'Gi ett eksempel der ioniserende stråling brukes til å undersøke, og ett der den brukes til å behandle. Forklar prinsippene.',answer:'Undersøkelse: røntgen/CT avbilder forskjeller i demping, eller PET viser fordeling av et radioaktivt sporstoff. Behandling: strålebehandling avsetter en planlagt dose som skader kreftceller, samtidig som friskt vev forsøkes spart.'},
    {id:'sv-q15',type:'open',level:'Bruk',prompt:'Forklar forskjellen på fisjon og fusjon, og hvordan kontrollstaver påvirker en fisjonsreaktor.',answer:'Fisjon deler en tung kjerne; fusjon slår sammen lette kjerner. Ved fisjon kan frigitte nøytroner utløse nye spaltinger. Kontrollstaver absorberer nøytroner og kan derfor regulere eller stanse kjedereaksjonen.'},
    {id:'sv-q16',type:'open',level:'Utfordring',prompt:'En elev sier: «Når sykehuset tar røntgenbilde av deg, blir du radioaktiv.» Forklar forskjellen på bestråling og radioaktiv forurensning.',answer:'Røntgenbildet tas ved at stråling fra et apparat passerer gjennom kroppen. Vanlig diagnostisk røntgen gjør deg ikke radioaktiv. Radioaktiv forurensning betyr at radioaktive stoffer finnes på eller inne i kroppen; det er noe annet enn å ha blitt bestrålt.'},
    {id:'sv-q17',type:'open',level:'Utfordring',prompt:'Drøft ett argument for kjernekraft og én utfordring som må håndteres. Knytt begge til egenskaper ved kjerneenergi.',answer:'Eksempel: mye energi fra lite brensel og lave direkte CO₂-utslipp under drift er en fordel. Radioaktive fisjonsprodukter krever sikker håndtering og langtidsløsninger; i tillegg er sikkerhet, kostnad og byggetid relevante. Et godt svar begrunner både fordel og utfordring.'}
  ],
  resources:[{label:'DSA: hva er ioniserende stråling?',url:'https://www.dsa.no/om-straling-og-radioaktivitet/hva-er-straling'},{label:'DSA: stråledoser',url:'https://www.dsa.no/om-straling-og-radioaktivitet/straledoser'},{label:'DSA: virkninger av ioniserende stråling',url:'https://www.dsa.no/om-straling-og-radioaktivitet/skadelige-effekter-av-ioniserende-straling'},{label:'DSA: radon',url:'https://www.dsa.no/radon'}],
  mount:mountProtection
}];
